<div class="table-scroll"><table><thead><tr><th>Software</th><th>Version</th><th>License type</th><th>Installation date</th><th>Status</th><th>Notes</th><?php if($canEditSoftware || $canDeleteSoftware || $canManageEmployeeCredentials): ?><th>Actions</th><?php endif; ?></tr></thead><tbody>
<?php foreach($software as $s): ?>
<tr><td><?=htmlspecialchars($s['software_name'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?></td><td><?=htmlspecialchars($s['version']??'—',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?></td><td><?=htmlspecialchars($s['license_type']??'—',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?></td><td><?=htmlspecialchars($s['installation_date']??'—',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?></td><td><span class="state-pill <?=htmlspecialchars($s['status'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?>"><?=htmlspecialchars(ucfirst($s['status']),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?></span></td><td><?=htmlspecialchars($s['notes']??'—',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?></td>
<?php if($canEditSoftware || $canDeleteSoftware || $canManageEmployeeCredentials): ?><td class="action-stack software-actions-cell"><?php if($s['status']==='installed'): ?><div class="software-row-actions">
<?php if($canEditSoftware || $canManageEmployeeCredentials): ?><button type="button" class="btn" data-open-software="<?=htmlspecialchars(json_encode($s,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP|JSON_INVALID_UTF8_SUBSTITUTE),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?>"><?=$canEditSoftware?'Manage Software':'View credentials'?></button><?php endif; ?>
<?php if($canDeleteSoftware): ?><form method="post" onsubmit="return confirm('Record this software as uninstalled?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf(),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?>"><input type="hidden" name="employee_id" value="<?=$employeeId?>"><input type="hidden" name="action" value="software_uninstall"><input type="hidden" name="software_id" value="<?=$s['id']?>"><input type="hidden" name="reason" value="Uninstalled by administrator"><button class="btn btn-danger" type="submit">Uninstall</button></form><?php endif; ?>
</div><?php else: ?>—<?php endif; ?></td><?php endif; ?></tr>
<?php endforeach; ?>
<?php if(!$software): ?><tr><td colspan="<?=($canEditSoftware || $canDeleteSoftware || $canManageEmployeeCredentials)?7:6?>" class="empty-state">No software records. Add an installation to get started.</td></tr><?php endif; ?>
</tbody></table></div>
